import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { FileService } from '../../core/services/file.service';
import { AuthService } from '../../core/services/auth.service';
import { Router } from '@angular/router';
import { ProfService } from '../../core/services/prof.service';
import {  OrderByDatePipe } from 'src/app/core/order-by-date.pipe';

@Component({
  selector: 'app-prof-dashboard',
  standalone: true,
  imports: [CommonModule, FormsModule,OrderByDatePipe],
  templateUrl: './prof-dashboard.component.html',
  styleUrls: ['./prof-dashboard.component.scss']
})
export class ProfDashboardComponent implements OnInit {
  files: any[] = [];
  classes: any[] = [];
  selectedClassId: number | null = null;

  title = '';
  type = 0;
  selectedFile: File | null = null;

  uploading = false;
  deletingId: number | null = null;
  loadingFiles = false;
resourceTypes = [
  { label: 'Cours', icon: '📘', color: 'text-primary', btnClass: 'btn-outline-primary' },
  { label: 'TD', icon: '🧩', color: 'text-success', btnClass: 'btn-outline-success' },
  { label: 'TP', icon: '🧪', color: 'text-warning', btnClass: 'btn-outline-warning' },
  { label: 'Autre', icon: '📄', color: 'text-danger', btnClass: 'btn-outline-danger' }
];

  constructor(
    private fileService: FileService,
    private auth: AuthService,
    private router: Router,
    private profService: ProfService
  ) {}

  ngOnInit() {
    this.loadClasses();
  }

  gotoClasses() {
    this.router.navigate(['/dashboard/classes']);
  }

  // 🧩 Charger les classes du professeur
  loadClasses() {
    this.profService.getMyClasses().subscribe({
      next: data => {
        this.classes = data;
        // Si au moins une classe existe → sélectionne la première
        if (this.classes.length > 0) {
          this.selectedClassId = this.classes[0].id;
          this.loadFiles();
        }
      },
      error: err => {
        console.error('Erreur chargement classes :', err);
        this.classes = [];
      }
    });
  }

  // 🧩 Charger les fichiers selon la classe sélectionnée
  loadFiles() {
    if (!this.selectedClassId) {
      this.files = [];
      return;
    }

    this.loadingFiles = true;
    this.fileService.getFilesByClass(this.selectedClassId).subscribe({
      next: res => {
        this.files = res || [];
        this.loadingFiles = false;
      },
      error: err => {
        console.error('Erreur chargement fichiers :', err);
        this.loadingFiles = false;
      }
    });
  }

  // 🧩 Upload d’un fichier
  onFileSelected(e: any) {
    this.selectedFile = e.target.files[0];
  }

  onUpload() {
    if (!this.selectedFile || !this.title || !this.selectedClassId) return;

    this.uploading = true;
    this.fileService.uploadFile(this.title, this.type, this.selectedFile, this.selectedClassId)
      .subscribe({
        next: () => {
          this.title = '';
          this.type = 0;
          this.selectedFile = null;
          this.loadFiles(); // recharge après upload
        },
        complete: () => this.uploading = false,
        error: () => this.uploading = false
      });
  }

  // 🧩 Suppression d’un fichier
  delete(id: number) {
    this.deletingId = id;
    this.fileService.deleteFile(id).subscribe({
      next: () => this.loadFiles(),
      complete: () => this.deletingId = null
    });
  }

  // 🧩 Label du type de ressource
  getTypeLabel(type: any): string {
  // Si c’est un nombre, on garde l’ancien switch
  if (typeof type === 'number') {
    switch (type) {
      case 0: return 'Cours';
      case 1: return 'TD';
      case 2: return 'TP';
      case 3: return 'Autre';
    }
  }

  // Si c’est une chaîne (envoyée par le backend)
  if (typeof type === 'string') {
    switch (type.toLowerCase()) {
      case 'cours': return 'Cours';
      case 'td': return 'TD';
      case 'tp': return 'TP';
      case 'autre': return 'Autre';
    }
  }

  return 'Inconnu';
}

}
<div class="dashboard-container">
  <div class="dashboard-header d-flex justify-content-between align-items-center">
    <div>
      <h1 class="dashboard-title">Tableau de bord</h1>
      <p class="dashboard-subtitle">Gérez et partagez vos ressources par classe</p>
    </div>

    <button class="btn btn-primary" (click)="gotoClasses()">
      <i class="bi bi-collection me-2"></i> Mes Classes
    </button>
  </div>

  <div class="row g-4 align-items-start">
    <!-- Section Upload -->
    <div class="col-12 col-lg-4">
      <div class="card p-4 shadow-sm">
        <h3 class="card-title mb-3">📤 Ajouter une ressource</h3>

        <form (ngSubmit)="onUpload()" class="upload-form">
          <div class="mb-3">
            <label class="form-label">Classe</label>
            <select class="form-select" [(ngModel)]="selectedClassId" name="classId" (change)="loadFiles()">
              <option *ngFor="let c of classes" [value]="c.id">{{ c.name }}</option>
            </select>
          </div>

          <div class="mb-3">
            <label class="form-label">Titre</label>
            <input class="form-control" [(ngModel)]="title" name="title" placeholder="Ex: TP n°1 BTP" required>
          </div>

          <div class="mb-3">
            <label class="form-label">Type</label>
            <select class="form-select" [(ngModel)]="type" name="type" required>
              <option [value]="0">Cours</option>
              <option [value]="1">TD</option>
              <option [value]="2">TP</option>
              <option [value]="3">Autre</option>
            </select>
          </div>

          <div class="mb-3">
            <label class="form-label">Fichier</label>
            <input type="file" class="form-control" (change)="onFileSelected($event)" required>
          </div>

          <button class="btn btn-primary w-100" [disabled]="uploading">
            <ng-container *ngIf="!uploading">
              <i class="bi bi-cloud-upload me-2"></i> Uploader
            </ng-container>
            <ng-container *ngIf="uploading">
              <span class="spinner-border spinner-border-sm"></span> Upload en cours...
            </ng-container>
          </button>
        </form>
      </div>
    </div>

    <!-- Section fichiers -->
    <div class="col-12 col-lg-8">
      <div class="card p-4 shadow-sm">
        <h3 class="section-title mb-4 text-center">📚 Ressources de la classe sélectionnée</h3>

        <div *ngIf="loadingFiles" class="text-center my-4">
          <div class="spinner-border text-primary"></div>
          <p class="mt-2 text-muted">Chargement des fichiers...</p>
        </div>

        <div *ngIf="!loadingFiles && files.length > 0; else noFiles">
          <!-- ✅ Bloc pour chaque type -->
          <div *ngFor="let type of resourceTypes" class="mb-4">
            <h4 class="fw-bold text-uppercase border-bottom pb-2 mb-3" [ngClass]="type.color">
              {{ type.icon }} {{ type.label }}
            </h4>

            <div class="files-grid">
              <div
                class="file-card shadow-sm"
                *ngFor="let f of files | orderByDate"
                [hidden]="getTypeLabel(f.type) !== type.label"
              >
                <h5 class="file-title">{{ f.title }}</h5>

                <p class="file-date text-muted small mb-2">
                  <i class="bi bi-calendar-event me-1"></i>
                  Ajouté le {{ f.createdAt | date: 'dd MMM yyyy, HH:mm' }}
                </p>

                <div class="file-actions">
                  <a [href]="f.fileUrl" target="_blank" class="btn btn-sm w-100 mb-2" [ngClass]="type.btnClass">
                    <i class="bi bi-download me-1"></i> Télécharger
                  </a>
                  <button class="btn btn-outline-danger btn-sm w-100" (click)="delete(f.id)">
                    <i class="bi bi-trash me-1"></i> Supprimer
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>

        <ng-template #noFiles>
          <div class="text-center text-muted py-4">
            📭 Aucune ressource disponible pour cette classe.
          </div>
        </ng-template>
      </div>
    </div>
  </div>
</div>
